import { NEW_ERUVIM } from './new_eruvim';

/**
 * Guards the KLBD boundaries regenerated by scripts/rebuild_klbd_eruvim.js.
 *
 * The original extraction concatenated disconnected line segments into a
 * "ring", producing an unclosed, self-intersecting shape that two different
 * eruvim shared. These tests fail if that ever happens again.
 */

const REBUILT = ['Brondesbury Park Eruv', "St John's Wood Eruv", 'Chigwell Eruv'];

// South Hampstead cannot be closed from the KLBD KML — its two open ends are
// 4,530m apart and the connecting coordinates are absent. It is expected to be
// present but is deliberately excluded from the correctness checks below.
const UNVERIFIED = ['South Hampstead Eruv'];

const byName = (n) => NEW_ERUVIM.find((e) => e.name === n);

const isClosed = (ring) =>
  ring.length > 2
  && Math.abs(ring[0].lat - ring[ring.length - 1].lat) < 1e-9
  && Math.abs(ring[0].lng - ring[ring.length - 1].lng) < 1e-9;

/** Planar signed area, in km². Fine at city scale. */
function areaKm2(ring) {
  const R = 6371008.8;
  const rad = (d) => (d * Math.PI) / 180;
  const lat0 = ring.reduce((s, p) => s + p.lat, 0) / ring.length;
  const kx = (Math.cos(rad(lat0)) * R * Math.PI) / 180;
  const ky = (R * Math.PI) / 180;
  let a = 0;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    a += ring[j].lng * kx * (ring[i].lat * ky) - ring[i].lng * kx * (ring[j].lat * ky);
  }
  return Math.abs(a / 2) / 1e6;
}

function selfIntersections(ring) {
  const side = (a, b, c) =>
    (b.lng - a.lng) * (c.lat - a.lat) - (b.lat - a.lat) * (c.lng - a.lng);
  const crosses = (p1, p2, p3, p4) => {
    const d1 = side(p3, p4, p1); const d2 = side(p3, p4, p2);
    const d3 = side(p1, p2, p3); const d4 = side(p1, p2, p4);
    return ((d1 > 0 && d2 < 0) || (d1 < 0 && d2 > 0))
      && ((d3 > 0 && d4 < 0) || (d3 < 0 && d4 > 0));
  };
  let n = 0;
  for (let i = 0; i < ring.length - 1; i += 1) {
    for (let j = i + 2; j < ring.length - 1; j += 1) {
      if (i === 0 && j === ring.length - 2) continue;
      if (crosses(ring[i], ring[i + 1], ring[j], ring[j + 1])) n += 1;
    }
  }
  return n;
}

function inRing(pt, ring) {
  let inside = false;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const xi = ring[i].lng; const yi = ring[i].lat;
    const xj = ring[j].lng; const yj = ring[j].lat;
    if ((yi > pt.lat) !== (yj > pt.lat)
      && pt.lng < ((xj - xi) * (pt.lat - yi)) / (yj - yi) + xi) inside = !inside;
  }
  return inside;
}

describe('NEW_ERUVIM', () => {
  it('contains every eruv the map expects to load', () => {
    [...REBUILT, ...UNVERIFIED].forEach((name) => {
      expect(byName(name)).toBeDefined();
    });
  });

  it('gives each eruv its own distinct boundary', () => {
    const paths = NEW_ERUVIM.map((e) => JSON.stringify(e.containmentPath));
    expect(new Set(paths).size).toBe(paths.length);
  });
});

describe.each(REBUILT)('%s', (name) => {
  const eruv = byName(name);

  it('has a containment path with real geometry', () => {
    expect(eruv.containmentPath.length).toBeGreaterThan(50);
    eruv.containmentPath.forEach((p) => {
      expect(Number.isFinite(p.lat)).toBe(true);
      expect(Number.isFinite(p.lng)).toBe(true);
      // Greater London, loosely
      expect(p.lat).toBeGreaterThan(51.3);
      expect(p.lat).toBeLessThan(51.8);
      expect(p.lng).toBeGreaterThan(-0.6);
      expect(p.lng).toBeLessThan(0.3);
    });
  });

  it('is a closed ring', () => {
    expect(isClosed(eruv.containmentPath)).toBe(true);
  });

  it('does not intersect itself', () => {
    expect(selfIntersections(eruv.containmentPath)).toBe(0);
  });

  it('encloses a plausible area for an eruv', () => {
    const a = areaKm2(eruv.containmentPath);
    expect(a).toBeGreaterThan(0.2);
    expect(a).toBeLessThan(25);
  });

  it('has a colour', () => {
    expect(eruv.color).toMatch(/^#[0-9A-Fa-f]{6}$/);
  });
});

describe('Brondesbury Park and St John\'s Wood', () => {
  const bp = byName('Brondesbury Park Eruv').containmentPath;
  const sjw = byName("St John's Wood Eruv").containmentPath;

  it('abut rather than overlap', () => {
    // St John's Wood is closed using Brondesbury Park's own coordinates, so a
    // wrong choice of arc would wrap one inside the other.
    const lats = sjw.map((p) => p.lat);
    const lngs = sjw.map((p) => p.lng);
    const G = 60;
    let shared = 0;
    for (let i = 0; i <= G; i += 1) {
      for (let j = 0; j <= G; j += 1) {
        const pt = {
          lat: Math.min(...lats) + (Math.max(...lats) - Math.min(...lats)) * (i / G),
          lng: Math.min(...lngs) + (Math.max(...lngs) - Math.min(...lngs)) * (j / G),
        };
        if (inRing(pt, sjw) && inRing(pt, bp)) shared += 1;
      }
    }
    expect(shared).toBe(0);
  });

  it('places Lord\'s Cricket Ground inside St John\'s Wood, not Brondesbury Park', () => {
    const lords = { lat: 51.5294, lng: -0.1729 };
    expect(inRing(lords, sjw)).toBe(true);
    expect(inRing(lords, bp)).toBe(false);
  });

  it('places Willesden Green inside Brondesbury Park, not St John\'s Wood', () => {
    const willesden = { lat: 51.5492, lng: -0.2215 };
    expect(inRing(willesden, bp)).toBe(true);
    expect(inRing(willesden, sjw)).toBe(false);
  });
});
